$$\begin{array}{l}
  {\int_{a}^{b}\mathbf{r}(t)dt = \lim\limits_{n\rightarrow\infty}\underset{i=1}{\overset{n}{\sum}}\mathbf{r}\left( t_{i}^{\ast} \right)\Delta t} \\
  {\phantom{\int_{a}^{b}\mathbf{r}(t)dt} = \lim\limits_{n\rightarrow\infty}\left\lbrack \left( \left. {\underset{i=1}{\overset{n}{\sum}}f}{\left( t_{i}^{\ast} \right)\Delta t} \right)\mathbf{i} + \left( {{\underset{i=1}{\overset{n}{\sum}}g}\left( t_{i}^{\ast} \right)\Delta t} \right)\mathbf{j} + \left( {{\underset{i=1}{\overset{n}{\sum}}h}\left( t_{i}^{\ast} \right)\Delta t} \right)\mathbf{k} \right. \right\rbrack}
  \end{array}$$

$$\begin{array}{rcl}
  {\mathbf{r}^{\prime}(t)} & = & {{- \sin t\mathbf{i} + \cos t\mathbf{j} + \mathbf{k}}\qquad\left| \mathbf{r}^{\prime}(t) \right| = \sqrt{2}} \\
  {\mathbf{T}(t)} & = & {\frac{\mathbf{r}^{\prime}(t)}{|\mathbf{r}^{\prime}(t)|} = \frac{1}{\sqrt{2}}( - \sin t\mathbf{i} + \cos t\mathbf{j} + \mathbf{k})} \\
  {\mathbf{T}^{\prime}(t)} & = & {{\frac{1}{\sqrt{2}}( - \cos t\mathbf{i} - \sin t\mathbf{j})}\qquad\left| \mathbf{T}^{\prime}(t) \right| = \frac{1}{\sqrt{2}}} \\
  {\mathbf{N}(t)} & = & {\frac{\mathbf{T}^{\prime}(t)}{\left| \mathbf{T}^{\prime}(t) \right|} = - \cos t\mathbf{i} - \sin t\mathbf{j} = \langle - \cos t, - \sin t,0\rangle}
  \end{array}$$

$$\begin{array}{rcl}
  {\mathbf{v}(t)} & = & {{\mathbf{r}^{\prime}(t) = \langle 2t},e^{ t},(1 + t)e^{ t}\rangle} \\
  {\mathbf{a}(t)} & = & {{\mathbf{v}^{\prime}(t) = \langle 2},e^{ t},(2 + t)e^{ t}\rangle} \\
  \left| \mathbf{v}(t) \right| & = & \sqrt{4t^{2} + e^{2t} + {(1 + t)}^{2}e^{2t}}
  \end{array}$$

$$\begin{array}{rcl}
  {\mathbf{v}(t)} & = & {\mathbf{r}^{\prime}(t) = - a\omega\sin\omega t\mathbf{i} + a\omega\cos\omega t\mathbf{j}} \\
  {\mathbf{a}(t)} & = & {\mathbf{v}^{\prime}(t) = - a\omega^{2}\cos\omega t\mathbf{i} - a\omega^{2}\sin\omega t\mathbf{j}}
  \end{array}$$
